<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Comments & Reviews';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['review_id'];$action=$_POST['action']??'status';$row=$pdo->prepare('SELECT product_id FROM product_reviews WHERE review_id=?');$row->execute([$id]);$pid=(int)$row->fetchColumn();if($action==='reply'){$reply=trim((string)$_POST['admin_reply']);if($reply==='')$err='Write a reply first.';else{$pdo->prepare('UPDATE product_reviews SET admin_reply=?,admin_reply_at=NOW(),admin_reply_by=? WHERE review_id=?')->execute([$reply,(int)$_SESSION['admin_id'],$id]);$msg='Public management reply saved.';}}else{$status=in_array($_POST['status'],['APPROVED','REJECTED','PENDING'],true)?$_POST['status']:'PENDING';$pdo->prepare('UPDATE product_reviews SET status=? WHERE review_id=?')->execute([$status,$id]);$msg='Comment moderation saved.';}$s=$pdo->prepare("SELECT COUNT(*),COALESCE(AVG(rating),0) FROM product_reviews WHERE product_id=? AND status='APPROVED'");$s->execute([$pid]);$agg=$s->fetch(PDO::FETCH_NUM);try{$pdo->prepare('UPDATE products SET review_count=?,rating=? WHERE product_id=?')->execute([(int)$agg[0],round((float)$agg[1],1),$pid]);}catch(Throwable $ignore){}}
$rows=$pdo->query('SELECT r.*,p.product_name,c.full_name FROM product_reviews r JOIN products p ON p.product_id=r.product_id JOIN customers c ON c.customer_id=r.customer_id ORDER BY r.created_at DESC')->fetchAll();require __DIR__.'/../includes/header.php';?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/products.php">Products</a><a href="/admin/orders.php">Orders</a><a href="/admin/customers.php">Members</a><a href="/admin/messages.php">Private chat</a><a class="active" href="/admin/reviews.php">Comments & reviews</a><?php if(super_admin()): ?><a href="/admin/users.php">Admin accounts</a><?php endif; ?><a href="/">View store</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">PUBLIC CUSTOMER FEEDBACK</span><h1>Comments & review control</h1><p>Approve public experiences and reply as Shadril Shopping Store.</p></div></div><?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?><?php if($err): ?><div class="errors"><?=e($err)?></div><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Product</th><th>Customer</th><th>Rating</th><th>Comment</th><th>Status</th><th>Management reply</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['product_name'])?></td><td><?=e($r['full_name'])?></td><td>★ <?=e((string)$r['rating'])?></td><td><?=e($r['comment'])?></td><td><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="review_id" value="<?=$r['review_id']?>"><select name="status"><option <?=$r['status']==='APPROVED'?'selected':''?>>APPROVED</option><option <?=$r['status']==='PENDING'?'selected':''?>>PENDING</option><option <?=$r['status']==='REJECTED'?'selected':''?>>REJECTED</option></select><button class="btn small">Save</button></form></td><td><form method="post" class="admin-reply-form"><?=csrf_field()?><input type="hidden" name="review_id" value="<?=$r['review_id']?>"><input type="hidden" name="action" value="reply"><textarea name="admin_reply" placeholder="Reply publicly..."><?=e($r['admin_reply']??'')?></textarea><button class="btn small">Reply</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php'; ?>